diff --git a/scripts/acceptance-journey.mjs b/scripts/acceptance-journey.mjs
new file mode 100644
index 0000000..eabc1a4
--- /dev/null
+++ b/scripts/acceptance-journey.mjs
@@ -0,0 +1,479 @@
+import AxeBuilder from "@axe-core/playwright";
+import { chromium } from "@playwright/test";
+
+import { isDonenessUpdateRequest } from "./acceptance-request-matcher.mjs";
+
+const applicationUrl = process.argv[2];
+
+if (!applicationUrl) {
+  throw new Error(
+    "The application URL is required for the acceptance journey."
+  );
+}
+
+const JOURNEY_HEIGHT = 844;
+const JOURNEY_VIEWPORTS = [375, 390, 430];
+const MAX_NATIVE_CONTROL_TABS = 4;
+const MINIMUM_TARGET_SIZE = 44;
+const DONENESS_FAILURE_PATTERN = /Unable to save doneness/;
+const JOURNEY_FIXTURES = [
+  {
+    corrected: { date: "2026-08-17", time: "14:15" },
+    failure: { date: "2026-08-24", time: "12:00" },
+    initial: { date: "2026-08-10", time: "10:00" },
+  },
+  {
+    corrected: { date: "2026-09-07", time: "14:15" },
+    failure: { date: "2026-09-14", time: "12:00" },
+    initial: { date: "2026-08-31", time: "10:00" },
+  },
+  {
+    corrected: { date: "2026-09-28", time: "14:15" },
+    failure: { date: "2026-10-05", time: "12:00" },
+    initial: { date: "2026-09-21", time: "10:00" },
+  },
+];
+
+function ensure(condition, message) {
+  if (!condition) {
+    throw new Error(message);
+  }
+}
+
+function describeViewport(viewport) {
+  return `${viewport.width}x${viewport.height}`;
+}
+
+function recentSightingPattern({ date, time }) {
+  const [year, month, day] = date.split("-").map(Number);
+  const [hour, minute] = time.split(":").map(Number);
+  const instant = new Date(Date.UTC(year, month - 1, day, hour, minute));
+  const formattedDate = new Intl.DateTimeFormat("en-US", {
+    day: "numeric",
+    month: "long",
+    timeZone: "UTC",
+    year: "numeric",
+  }).format(instant);
+  const formattedTime = new Intl.DateTimeFormat("en-US", {
+    hour: "numeric",
+    minute: "2-digit",
+    timeZone: "UTC",
+  }).format(instant);
+
+  return new RegExp(`${formattedDate} at ${formattedTime}`);
+}
+
+async function expectVisible(locator, description) {
+  await locator.waitFor({ state: "visible" });
+  ensure(await locator.isVisible(), `${description} is visible`);
+}
+
+async function assertNoHorizontalOverflow(page, description) {
+  const dimensions = await page.evaluate(() => ({
+    clientWidth: document.documentElement.clientWidth,
+    scrollWidth: document.documentElement.scrollWidth,
+  }));
+
+  ensure(
+    dimensions.scrollWidth <= dimensions.clientWidth,
+    `${description} does not overflow horizontally (${dimensions.scrollWidth}px > ${dimensions.clientWidth}px)`
+  );
+}
+
+async function assertTouchTargets(page, description) {
+  const undersizedTargets = await page
+    .locator("a, button, input, select")
+    .evaluateAll(
+      (elements, minimumTargetSize) =>
+        elements.flatMap((element) => {
+          const rectangle = element.getBoundingClientRect();
+          const name =
+            element.getAttribute("aria-label") ||
+            element.textContent?.trim() ||
+            element.getAttribute("id") ||
+            element.tagName.toLowerCase();
+
+          return rectangle.width >= minimumTargetSize &&
+            rectangle.height >= minimumTargetSize
+            ? []
+            : [
+                {
+                  height: Math.round(rectangle.height),
+                  name,
+                  width: Math.round(rectangle.width),
+                },
+              ];
+        }),
+      MINIMUM_TARGET_SIZE
+    );
+
+  ensure(
+    undersizedTargets.length === 0,
+    `${description} has an interactive target below ${MINIMUM_TARGET_SIZE}px: ${JSON.stringify(undersizedTargets)}`
+  );
+}
+
+async function assertAccessibility(page, description) {
+  const results = await new AxeBuilder({ page }).analyze();
+  const blockingViolations = results.violations.filter(
+    (violation) =>
+      violation.impact === "critical" || violation.impact === "serious"
+  );
+
+  ensure(
+    blockingViolations.length === 0,
+    `${description} has serious or critical axe violations: ${JSON.stringify(blockingViolations)}`
+  );
+
+  await assertNoHorizontalOverflow(page, description);
+  await assertTouchTargets(page, description);
+}
+
+async function assertLiveRegion(locator, expectedLive, description) {
+  await expectVisible(locator, description);
+  ensure(
+    (await locator.getAttribute("aria-live")) === expectedLive,
+    `${description} has aria-live=${expectedLive}`
+  );
+}
+
+async function assertAlert(locator, description) {
+  await assertLiveRegion(locator, "assertive", description);
+  ensure(
+    (await locator.getAttribute("role")) === "alert",
+    `${description} has role=alert`
+  );
+}
+
+async function openCapture(page) {
+  await page.goto(applicationUrl, { waitUntil: "networkidle" });
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture heading"
+  );
+}
+
+async function saveSighting(page, labelDate, labelTime) {
+  await page.locator("#label-date").fill(labelDate);
+  await page.locator("#label-time").fill(labelTime);
+  await page.getByRole("button", { name: "Save label time" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Sighting saved" }),
+    "completion heading"
+  );
+}
+
+async function assertFocused(locator, description) {
+  await locator.waitFor({ state: "visible" });
+  const isFocused = await locator.evaluate(
+    (element) => document.activeElement === element
+  );
+  ensure(isFocused, `${description} receives focus`);
+}
+
+async function pressUntilFocused(page, locator, key, description) {
+  for (
+    let pressCount = 0;
+    pressCount < MAX_NATIVE_CONTROL_TABS;
+    pressCount += 1
+  ) {
+    await page.keyboard.press(key);
+    const isFocused = await locator.evaluate(
+      (element) => document.activeElement === element
+    );
+
+    if (isFocused) {
+      return;
+    }
+  }
+
+  await assertFocused(locator, description);
+}
+
+async function runFullJourney(page, viewport, fixtureIndex) {
+  const fixture = JOURNEY_FIXTURES[fixtureIndex];
+  ensure(fixture, `fixture exists for ${describeViewport(viewport)}`);
+  const initialSightingPattern = recentSightingPattern(fixture.initial);
+  const correctedSightingPattern = recentSightingPattern(fixture.corrected);
+  const failureSightingPattern = recentSightingPattern(fixture.failure);
+  const expectedCorrectedSightingId = 3 + fixtureIndex * 3;
+  const expectedFailureSightingId = 4 + fixtureIndex * 3;
+  const viewportDescription = describeViewport(viewport);
+
+  await openCapture(page);
+  await expectVisible(page.getByRole("main"), "main landmark");
+  await expectVisible(
+    page.getByRole("navigation", { name: "Primary navigation" }),
+    "navigation"
+  );
+  await expectVisible(page.locator("#label-time"), "labelled time input");
+  await expectVisible(page.locator("#label-date"), "labelled date input");
+  await assertAccessibility(page, `initial Capture at ${viewportDescription}`);
+
+  await page.locator("#label-time").focus();
+  await assertFocused(page.locator("#label-time"), "Capture label-time input");
+  await pressUntilFocused(
+    page,
+    page.locator("#label-date"),
+    "Tab",
+    "Capture label-date input after Tab"
+  );
+  await pressUntilFocused(
+    page,
+    page.locator("#label-time"),
+    "Shift+Tab",
+    "Capture label-time input after Shift+Tab"
+  );
+  await page.locator("#label-date").fill(fixture.initial.date);
+  await page.locator("#label-time").fill(fixture.initial.time);
+  await page.locator("#label-time").focus();
+  await page.keyboard.press("Enter");
+  await expectVisible(
+    page.getByRole("heading", { name: "Sighting saved" }),
+    "completion heading after keyboard submit"
+  );
+  await assertFocused(
+    page.getByRole("heading", { name: "Sighting saved" }),
+    "completion heading"
+  );
+  await assertAccessibility(page, `completion at ${viewportDescription}`);
+
+  await page.reload({ waitUntil: "networkidle" });
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture after reload"
+  );
+  const persistedSighting = page.getByRole("button", {
+    name: initialSightingPattern,
+  });
+  await expectVisible(
+    persistedSighting,
+    "recent sighting after reload before enrichment"
+  );
+  await persistedSighting.click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Correct sighting" }),
+    "correction heading"
+  );
+  await assertFocused(
+    page.getByRole("heading", { name: "Correct sighting" }),
+    "correction heading"
+  );
+  await assertAccessibility(page, `correction at ${viewportDescription}`);
+  await page.getByRole("button", { name: "Cancel" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture after cancel"
+  );
+
+  await saveSighting(page, fixture.corrected.date, "14:05");
+  await page.getByRole("button", { name: "Medium" }).focus();
+  await assertFocused(
+    page.getByRole("button", { name: "Medium" }),
+    "Medium doneness button"
+  );
+  const correctedDonenessRequest = page.waitForRequest((request) =>
+    isDonenessUpdateRequest(
+      {
+        body: request.postData() ?? "",
+        method: request.method(),
+        url: request.url(),
+      },
+      {
+        doneness: "medium",
+        id: expectedCorrectedSightingId,
+        url: request.url(),
+      }
+    )
+  );
+  await page.keyboard.press("Space");
+  const donenessUpdateUrl = (await correctedDonenessRequest).url();
+  await assertLiveRegion(
+    page.getByText("Doneness saved as medium."),
+    "polite",
+    "doneness status"
+  );
+  await page.getByRole("button", { name: "Correct this sighting" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Correct sighting" }),
+    "completion correction"
+  );
+  await page.getByLabel("Label time").fill("14:15");
+  await page.getByLabel("Doneness").selectOption("dark");
+  await page.getByRole("button", { name: "Save correction" }).focus();
+  await page.keyboard.press("Enter");
+  await expectVisible(
+    page.getByRole("heading", { name: "Sighting saved" }),
+    "completion after correction"
+  );
+  await expectVisible(
+    page.getByText(correctedSightingPattern),
+    "corrected label time"
+  );
+  await assertAccessibility(
+    page,
+    `completion after correction at ${viewportDescription}`
+  );
+  await page.getByRole("button", { exact: true, name: "Done" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture after Done"
+  );
+  ensure(
+    !new URL(page.url()).searchParams.has("completion"),
+    "Done removes the completion recovery URL"
+  );
+
+  await expectVisible(
+    page.getByRole("heading", { name: "Recent Sightings" }),
+    "recent heading"
+  );
+  await page.getByRole("button", { name: correctedSightingPattern }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Correct sighting" }),
+    "recent correction"
+  );
+  await assertAccessibility(
+    page,
+    `deletion confirmation at ${viewportDescription}`
+  );
+  await page.getByRole("button", { name: "Delete sighting" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Permanently delete this sighting?" }),
+    "deletion confirmation"
+  );
+  await assertFocused(
+    page.getByRole("heading", { name: "Permanently delete this sighting?" }),
+    "deletion confirmation heading"
+  );
+  await page.getByRole("button", { name: "Permanently delete" }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture after deletion"
+  );
+  ensure(
+    (await page
+      .getByRole("button", { name: correctedSightingPattern })
+      .count()) === 0,
+    "deleted sighting is absent from Recent Sightings"
+  );
+
+  await page.getByRole("link", { name: "Plan" }).focus();
+  await assertFocused(page.getByRole("link", { name: "Plan" }), "Plan link");
+  await page.keyboard.press("Enter");
+  await expectVisible(
+    page.getByRole("heading", { name: "Plan" }),
+    "Plan heading"
+  );
+  await page.getByLabel("Weekday", { exact: true }).selectOption("0");
+  await expectVisible(
+    page.getByRole("heading", { name: "No history for this weekday" }),
+    "no-weekday-history state"
+  );
+  await page.getByLabel("Weekday", { exact: true }).selectOption("1");
+  await page.getByLabel("Approximate time").fill("10:00");
+  await expectVisible(
+    page.getByRole("heading", { name: "Not enough history to compare yet" }),
+    "sparse Plan state"
+  );
+  await assertAccessibility(page, `Plan at ${viewportDescription}`);
+
+  await page
+    .getByRole("navigation", { name: "Primary navigation" })
+    .getByRole("link", { name: "Capture" })
+    .click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture before failure case"
+  );
+  await saveSighting(page, fixture.failure.date, fixture.failure.time);
+
+  const interceptedRequests = [];
+  await page.route(donenessUpdateUrl, async (route) => {
+    const request = route.request();
+    const isDonenessUpdate = isDonenessUpdateRequest(
+      {
+        body: request.postData() ?? "",
+        method: request.method(),
+        url: request.url(),
+      },
+      {
+        doneness: "light",
+        id: expectedFailureSightingId,
+        url: donenessUpdateUrl,
+      }
+    );
+
+    if (isDonenessUpdate) {
+      interceptedRequests.push({
+        body: request.postData() ?? "",
+        url: request.url(),
+      });
+      await route.abort("failed");
+      return;
+    }
+
+    await route.continue();
+  });
+  await page.getByRole("button", { name: "Light" }).click();
+  await assertAlert(
+    page.getByText(DONENESS_FAILURE_PATTERN),
+    "enrichment failure"
+  );
+  ensure(
+    interceptedRequests.length === 1,
+    "exactly one doneness request was intercepted"
+  );
+  await assertAccessibility(
+    page,
+    `enrichment failure at ${viewportDescription}`
+  );
+  await page.unroute(donenessUpdateUrl);
+  await page.reload({ waitUntil: "networkidle" });
+  await expectVisible(
+    page.getByRole("heading", { name: "Capture" }),
+    "Capture after enrichment failure"
+  );
+  await page.getByRole("button", { name: failureSightingPattern }).click();
+  await expectVisible(
+    page.getByRole("heading", { name: "Correct sighting" }),
+    "correction after enrichment failure"
+  );
+  await assertAccessibility(
+    page,
+    `correction after enrichment failure at ${viewportDescription}`
+  );
+}
+
+async function runJourneysAtAllViewports(browser) {
+  for (const [fixtureIndex, width] of JOURNEY_VIEWPORTS.entries()) {
+    const viewport = { height: JOURNEY_HEIGHT, width };
+    const context = await browser.newContext({ viewport });
+    const page = await context.newPage();
+
+    try {
+      await runFullJourney(page, viewport, fixtureIndex);
+    } finally {
+      await context.close();
+    }
+  }
+}
+
+const browser = await chromium.launch({
+  executablePath: process.env.BROWSER_EXECUTABLE_PATH,
+  headless: true,
+});
+
+try {
+  await runJourneysAtAllViewports(browser);
+  console.log(
+    JSON.stringify({
+      browser:
+        process.env.ACCEPTANCE_BROWSER_LABEL ?? `Chromium ${browser.version()}`,
+      result: "passed",
+      viewports: JOURNEY_VIEWPORTS,
+    })
+  );
+} finally {
+  await browser.close();
+}
diff --git a/scripts/acceptance-request-matcher.mjs b/scripts/acceptance-request-matcher.mjs
new file mode 100644
index 0000000..61ac76e
--- /dev/null
+++ b/scripts/acceptance-request-matcher.mjs
@@ -0,0 +1,29 @@
+import { fromJSON } from "seroval";
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null;
+}
+
+function deserializeRequestData(body) {
+  try {
+    const payload = fromJSON(JSON.parse(body));
+
+    if (!(isRecord(payload) && isRecord(payload.data))) {
+      return undefined;
+    }
+
+    return payload.data;
+  } catch {
+    return undefined;
+  }
+}
+
+export function isDonenessUpdateRequest(request, expected) {
+  if (request.method !== "POST" || request.url !== expected.url) {
+    return false;
+  }
+
+  const data = deserializeRequestData(request.body);
+
+  return data?.id === expected.id && data.doneness === expected.doneness;
+}
diff --git a/scripts/acceptance-request-matcher.test.ts b/scripts/acceptance-request-matcher.test.ts
new file mode 100644
index 0000000..db6e050
--- /dev/null
+++ b/scripts/acceptance-request-matcher.test.ts
@@ -0,0 +1,65 @@
+import { toJSONAsync } from "seroval";
+import { describe, expect, it } from "vitest";
+
+import { isDonenessUpdateRequest } from "./acceptance-request-matcher.mjs";
+
+const DONENESS_UPDATE_URL =
+  "http://127.0.0.1:3000/_serverFn/update-doneness-function-id";
+
+async function serializeRequestData(
+  data: Record<string, unknown>
+): Promise<string> {
+  return JSON.stringify(await toJSONAsync({ data }));
+}
+
+describe("isDonenessUpdateRequest", () => {
+  it("identifies the exact server-function endpoint and Seroval-encoded fixture input", async () => {
+    const request = {
+      body: await serializeRequestData({ doneness: "light", id: 4 }),
+      method: "POST",
+      url: DONENESS_UPDATE_URL,
+    };
+
+    expect(
+      isDonenessUpdateRequest(request, {
+        doneness: "light",
+        id: 4,
+        url: DONENESS_UPDATE_URL,
+      })
+    ).toBe(true);
+  });
+
+  it("does not match another server function or a different fixture input", async () => {
+    const request = {
+      body: await serializeRequestData({ doneness: "medium", id: 3 }),
+      method: "POST",
+      url: DONENESS_UPDATE_URL,
+    };
+
+    expect(
+      isDonenessUpdateRequest(request, {
+        doneness: "light",
+        id: 4,
+        url: DONENESS_UPDATE_URL,
+      })
+    ).toBe(false);
+    expect(
+      isDonenessUpdateRequest(
+        {
+          ...request,
+          url: "http://127.0.0.1:3000/_serverFn/another-function-id",
+        },
+        { doneness: "medium", id: 3, url: DONENESS_UPDATE_URL }
+      )
+    ).toBe(false);
+  });
+
+  it("does not match malformed request data", () => {
+    expect(
+      isDonenessUpdateRequest(
+        { body: "not JSON", method: "POST", url: DONENESS_UPDATE_URL },
+        { doneness: "light", id: 4, url: DONENESS_UPDATE_URL }
+      )
+    ).toBe(false);
+  });
+});
